18	  steps: Step[];
19	};
20	
21	export type Result = {
22	  premium: number;
23	};
24	
25	export type ScenarioOutcome = {
26	  results: Result[];
27	};
28	
29	const PROCESSING_FEE = 5;
30	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	// Percentages are applied as the exact fraction `amount * percent / 100`
40	// rather than via a float factor such as `amount * 0.1`, which drifts.
41	const percentOf = (percent: number, amount: number): number =>
42	  (amount * percent) / 100;
43	
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	const CURSE_SURCHARGE_PERCENT = 50;
46	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	
49	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
50	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
51	
52	// Surcharges attached to a single item are a percentage of that item's own
53	// base premium from the price list (never of the policy base premium).
54	const surchargeForItem = (item: Item): number => {
55	  const itemBasePremium = BASE_PREMIUM_BY_TYPE[item.type];
56	  let surcharge = 0;
57	  if (item.cursed) {
58	    surcharge += percentOf(CURSE_SURCHARGE_PERCENT, itemBasePremium);
59	  }
60	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
61	    surcharge += percentOf(HIGH_ENCHANTMENT_SURCHARGE_PERCENT, itemBasePremium);
62	  }
63	  return surcharge;
64	};
65	
66	const itemSurchargesOf = (items: Item[]): number =>
67	  items.reduce((total, item) => total + surchargeForItem(item), 0);
68	
69	const BLOCK_SIZE = 3;
70	const BLOCK_BASE_PREMIUM = 60;
71	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
72	
73	const countByType = (items: Item[]): Map<string, number> => {
74	  const counts = new Map<string, number>();
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	  return counts;
79	};
80	
81	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
82	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
83	// items never form a block.
84	const basePremiumForAlikeItems = (type: string, count: number): number =>
85	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
86	    ? BLOCK_BASE_PREMIUM
87	    : count * BASE_PREMIUM_BY_TYPE[type];
88	
89	const policyBasePremiumOf = (items: Item[]): number =>
90	  [...countByType(items)].reduce(
91	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
92	    0,
93	  );
94	
95	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
96	  const results = scenario.steps.map((step) => {
97	    const policyBasePremium = policyBasePremiumOf(step.items);
98	    const premium =
99	      policyBasePremium +
100	      itemSurchargesOf(step.items) +
101	      firstInsuranceSurchargeOn(policyBasePremium) +
102	      PROCESSING_FEE;
103	    return { premium };
104	  });
105	
106	  return { results };
107	};
